#include <iostream>
#include <vector>
#include <numeric>

int main() {
    int n, h;
    std::cin >> n >> h;
    std::vector<long long> t(n + 1, 1), s(n + 1, 1);
    for (int m = 1; m <= n; ++m) {
        s[m] = 0;
        for (int k = 0; k < m; ++k) {
            s[m] += s[m - 1 - k] * s[k];
        }
    }
    for (int j = 0; j < h; ++j) {
        std::vector<long long> new_t(n + 1, 0);
        for (int m = 0; m <= n; ++m) {
            long long sum_val = 0;
            for (int k = 0; k <= m; ++k) {
                sum_val += (s[k] - t[k]) * t[m - 1 - k] + s[m - 1 - k] * t[k];
            }
            new_t[m] = sum_val;
        }
        t = new_t;
    }
    std::cout << t[n] << std::endl;
    return 0;
}
